export default {
 "junction_warning.ino": "// TransitSense · Junction warning post (one node per approach)\n// Hardware: ESP32 DevKitC · Benewake TFmini-S LiDAR · WS2812B 16-LED ring\n// Board: \"ESP32 Dev Module\" (Arduino-ESP32 core 3.x) · Library: Adafruit NeoPixel\n//\n// Each post measures the distance to the vehicle on its own approach.\n// A vehicle that keeps getting closer is \"approaching\"; parked (steady)\n// and departing (moving away) vehicles are ignored. The four posts share\n// their state over ESP-NOW: while one approach is active, its post stays\n// green and the other three show red. If a peer or the LiDAR goes silent,\n// the post fails safe to steady red.\n\n#include <WiFi.h>\n#include <esp_now.h>\n#include <Adafruit_NeoPixel.h>\n\nconst uint8_t APPROACH_ID = 0;          // 0 = North, 1 = West, 2 = South, 3 = East (set per post)\n\nconst int LIDAR_RX = 16;                // ESP32 RX2  <- TFmini-S TX\nconst int LIDAR_TX = 17;                // ESP32 TX2  -> TFmini-S RX\nconst int LED_PIN = 4;                  // WS2812B DIN (through a 330 Ω resistor)\nconst int LED_COUNT = 16;\n\nconst uint16_t WARN_RANGE_CM = 1100;    // only watch the last 11 m before the junction\nconst uint16_t MIN_STRENGTH = 100;      // reject weak or saturated LiDAR returns\nconst float APPROACH_SPEED_MS = 0.8;    // closing speed that counts as approaching\nconst uint32_t HOLD_MS = 2500;          // keep the warning this long after the last approach reading\nconst uint32_t PEER_TIMEOUT_MS = 1500;  // a silent peer means fail-safe red\nconst uint32_t LIDAR_TIMEOUT_MS = 500;  // a silent LiDAR means fail-safe red\nconst uint32_t HEARTBEAT_MS = 200;\n\nstruct PostMessage {\n  uint8_t id;\n  bool approaching;\n  uint32_t sequence;\n};\n\nAdafruit_NeoPixel ring(LED_COUNT, LED_PIN, NEO_GRB + NEO_KHZ800);\nconst uint8_t BROADCAST[6] = {0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF};\n\nvolatile bool peerApproaching[4] = {false, false, false, false};\nvolatile uint32_t peerLastSeen[4] = {0, 0, 0, 0};\n\nfloat smoothedSpeed = 0;\nuint16_t lastDistance = 0;\nuint32_t lastLidarFrame = 0, lastDistanceTime = 0, approachUntil = 0, lastHeartbeat = 0, sequence = 0;\n\nvoid onReceive(const esp_now_recv_info_t *info, const uint8_t *data, int len) {\n  if (len != sizeof(PostMessage)) return;\n  PostMessage msg;\n  memcpy(&msg, data, sizeof(msg));\n  if (msg.id > 3 || msg.id == APPROACH_ID) return;\n  peerApproaching[msg.id] = msg.approaching;\n  peerLastSeen[msg.id] = millis();\n}\n\n// One TFmini-S frame is 9 bytes: 0x59 0x59 distL distH strengthL strengthH tempL tempH checksum.\n// The checksum is the low byte of the sum of the first eight bytes. Distance is in centimetres.\nbool readLidar(uint16_t &distanceCm, uint16_t &strength) {\n  while (Serial2.available() >= 9) {\n    if (Serial2.read() != 0x59 || Serial2.peek() != 0x59) continue;\n    uint8_t frame[9] = {0x59};\n    Serial2.readBytes(frame + 1, 8);\n    uint8_t sum = 0;\n    for (int i = 0; i < 8; i++) sum += frame[i];\n    if (sum != frame[8]) continue;\n    distanceCm = frame[2] | (frame[3] << 8);\n    strength = frame[4] | (frame[5] << 8);\n    return true;\n  }\n  return false;\n}\n\nvoid updateApproach() {\n  uint16_t distance, strength;\n  if (!readLidar(distance, strength)) return;\n  uint32_t now = millis();\n  lastLidarFrame = now;\n  bool valid = strength >= MIN_STRENGTH && strength != 65535 && distance > 0 && distance < WARN_RANGE_CM;\n  if (valid && lastDistanceTime) {\n    float dt = (now - lastDistanceTime) / 1000.0;\n    if (dt > 0) {\n      float speed = (lastDistance - (float)distance) / 100.0 / dt;  // positive = getting closer\n      smoothedSpeed = 0.8 * smoothedSpeed + 0.2 * speed;\n    }\n  } else if (!valid) {\n    smoothedSpeed = 0;\n  }\n  if (valid) {\n    lastDistance = distance;\n    lastDistanceTime = now;\n    if (smoothedSpeed > APPROACH_SPEED_MS) approachUntil = now + HOLD_MS;\n  } else {\n    lastDistanceTime = 0;\n  }\n}\n\nvoid showColor(uint8_t r, uint8_t g, uint8_t b) {\n  ring.fill(ring.Color(r, g, b));\n  ring.show();\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  Serial2.begin(115200, SERIAL_8N1, LIDAR_RX, LIDAR_TX);\n  ring.begin();\n  ring.setBrightness(180);\n  showColor(255, 0, 0);  // red until the network is up\n\n  WiFi.mode(WIFI_STA);\n  if (esp_now_init() != ESP_OK) {\n    Serial.println(\"ESP-NOW init failed; staying red\");\n    while (true) delay(1000);\n  }\n  esp_now_register_recv_cb(onReceive);\n  esp_now_peer_info_t peer = {};\n  memcpy(peer.peer_addr, BROADCAST, 6);\n  peer.channel = 0;\n  peer.encrypt = false;\n  esp_now_add_peer(&peer);\n}\n\nvoid loop() {\n  updateApproach();\n  uint32_t now = millis();\n  bool selfApproaching = now < approachUntil;\n\n  if (now - lastHeartbeat >= HEARTBEAT_MS) {\n    lastHeartbeat = now;\n    PostMessage msg = {APPROACH_ID, selfApproaching, sequence++};\n    esp_now_send(BROADCAST, (const uint8_t *)&msg, sizeof(msg));\n  }\n\n  bool failSafe = now - lastLidarFrame > LIDAR_TIMEOUT_MS;\n  bool otherApproaching = false;\n  for (uint8_t i = 0; i < 4; i++) {\n    if (i == APPROACH_ID) continue;\n    if (now - peerLastSeen[i] > PEER_TIMEOUT_MS) failSafe = true;\n    if (peerApproaching[i]) otherApproaching = true;\n  }\n\n  if (failSafe) showColor(255, 0, 0);                                // steady red: fail-safe\n  else if (otherApproaching && !selfApproaching) showColor(255, 0, 0);  // cross traffic coming\n  else showColor(0, 255, 60);                                         // clear, or this approach has priority\n  delay(10);\n}\n",
 "siren_priority.ino": "// TransitSense · Ambulance priority (acoustic siren locator)\n// Hardware: ESP32 DevKitC · 2× INMP441 I2S MEMS microphones · PC817 optocoupler to the signal controller\n// Board: \"ESP32 Dev Module\" (Arduino-ESP32 core 3.x) · Library: arduinoFFT 2.x\n//\n// Both microphones share one I2S bus: Mic A has L/R tied to GND (left slot),\n// Mic B has L/R tied to 3.3 V (right slot), so every stereo frame holds one\n// synchronised sample from each. For each 64 ms block the sketch:\n//   1. finds the loudest frequency (FFT). Sirens sweep between ~500 and 1800 Hz;\n//   2. measures the time difference between the microphones (cross-correlation)\n//      to get the direction the sound comes from;\n//   3. checks that the sound is getting louder (a real approach). A reflection off\n//      a building is steady or fading and usually has a weak correlation peak.\n// When all three agree, the PREEMPT output asks the signal controller to clear\n// the junction and hold the ambulance's approach green.\n\n#include <ESP_I2S.h>\n#include <arduinoFFT.h>\n\nconst int I2S_SCK = 26, I2S_WS = 25, I2S_SD = 33;  // shared by both INMP441s\nconst int PREEMPT_PIN = 27;                         // drives the optocoupler LED (HIGH = request priority)\nconst int STATUS_LED = 2;\n\nconst uint32_t SAMPLE_RATE = 16000;\nconst uint16_t N = 1024;                 // samples per block (64 ms)\nconst float MIC_SPACING_M = 0.50;        // distance between the two microphones\nconst float SOUND_SPEED = 343.0;\nconst int MAX_LAG = 24;                  // ≥ spacing / (speed / rate) = 23.3 samples\n\nconst float SIREN_MIN_HZ = 500, SIREN_MAX_HZ = 1800;\nconst float MIN_SWEEP_HZ = 150;          // a siren's pitch must move by at least this much\nconst float MIN_RISE_DB = 1.5;           // level increase across the history window\nconst float MAX_BEARING_DEG = 35;        // accept sirens within ±35° of the approach axis\nconst uint32_t RELEASE_MS = 3000;        // keep priority this long after the siren stops\n\nconst int HISTORY = 24;                  // ~1.5 s of blocks\n\nI2SClass i2s;\nint32_t raw[N * 2];\nfloat left[N], right[N];\ndouble vReal[N], vImag[N];\nArduinoFFT<double> fft(vReal, vImag, N, SAMPLE_RATE);\n\nfloat peakHistory[HISTORY], levelHistory[HISTORY];\nint historyCount = 0;\nuint32_t lastConfirmed = 0;\n\nvoid pushHistory(float *history, float value) {\n  memmove(history, history + 1, (HISTORY - 1) * sizeof(float));\n  history[HISTORY - 1] = value;\n}\n\nfloat average(const float *values, int from, int to) {\n  float sum = 0;\n  for (int i = from; i < to; i++) sum += values[i];\n  return sum / (to - from);\n}\n\n// Returns the lag (in samples) where the two channels line up best, and how\n// clearly it stands out compared with the average correlation.\nint bestLag(float &sharpness) {\n  float best = -1e30, total = 0;\n  int lagAtBest = 0;\n  for (int lag = -MAX_LAG; lag <= MAX_LAG; lag++) {\n    float sum = 0;\n    for (int i = MAX_LAG; i < N - MAX_LAG; i++) sum += left[i] * right[i + lag];\n    total += fabsf(sum);\n    if (sum > best) { best = sum; lagAtBest = lag; }\n  }\n  float mean = total / (2 * MAX_LAG + 1);\n  sharpness = mean > 0 ? best / mean : 0;\n  return lagAtBest;\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(PREEMPT_PIN, OUTPUT);\n  pinMode(STATUS_LED, OUTPUT);\n  digitalWrite(PREEMPT_PIN, LOW);\n  i2s.setPins(I2S_SCK, I2S_WS, -1, I2S_SD);\n  if (!i2s.begin(I2S_MODE_STD, SAMPLE_RATE, I2S_DATA_BIT_WIDTH_32BIT, I2S_SLOT_MODE_STEREO)) {\n    Serial.println(\"I2S init failed\");\n    while (true) delay(1000);\n  }\n}\n\nvoid loop() {\n  size_t bytes = i2s.readBytes((char *)raw, sizeof(raw));\n  if (bytes < sizeof(raw)) return;\n\n  // INMP441 sends 24-bit samples left-aligned in 32-bit slots.\n  float meanL = 0, meanR = 0;\n  for (int i = 0; i < N; i++) {\n    left[i] = (raw[2 * i] >> 8) / 8388608.0;\n    right[i] = (raw[2 * i + 1] >> 8) / 8388608.0;\n    meanL += left[i];\n    meanR += right[i];\n  }\n  meanL /= N;\n  meanR /= N;\n  float energy = 0;\n  for (int i = 0; i < N; i++) {\n    left[i] -= meanL;\n    right[i] -= meanR;\n    energy += left[i] * left[i] + right[i] * right[i];\n    vReal[i] = left[i] + right[i];\n    vImag[i] = 0;\n  }\n  float levelDb = 10 * log10f(energy / (2 * N) + 1e-12);\n\n  fft.windowing(FFTWindow::Hamming, FFTDirection::Forward);\n  fft.compute(FFTDirection::Forward);\n  fft.complexToMagnitude();\n  float peakHz = fft.majorPeak();\n\n  pushHistory(peakHistory, peakHz);\n  pushHistory(levelHistory, levelDb);\n  if (historyCount < HISTORY) historyCount++;\n\n  float sharpness;\n  int lag = bestLag(sharpness);\n  float ratio = constrain(lag * SOUND_SPEED / SAMPLE_RATE / MIC_SPACING_M, -1.0, 1.0);\n  float bearingDeg = degrees(asinf(ratio));  // 0° = straight down the approach, sign = side\n\n  bool inBand = true;\n  float lowest = 1e9, highest = 0;\n  for (int i = HISTORY - 8; i < HISTORY; i++) {\n    inBand &= peakHistory[i] >= SIREN_MIN_HZ && peakHistory[i] <= SIREN_MAX_HZ;\n    lowest = min(lowest, peakHistory[i]);\n    highest = max(highest, peakHistory[i]);\n  }\n  bool sweeping = highest - lowest >= MIN_SWEEP_HZ;\n  bool rising = average(levelHistory, HISTORY - 8, HISTORY) - average(levelHistory, 0, 8) >= MIN_RISE_DB;\n  bool clearDirection = sharpness > 3.0 && fabsf(bearingDeg) <= MAX_BEARING_DEG;\n\n  bool siren = historyCount == HISTORY && inBand && sweeping;\n  if (siren && rising && clearDirection) lastConfirmed = millis();\n  bool priority = lastConfirmed && millis() - lastConfirmed < RELEASE_MS;\n\n  digitalWrite(PREEMPT_PIN, priority ? HIGH : LOW);\n  digitalWrite(STATUS_LED, priority ? HIGH : LOW);\n\n  Serial.printf(\"peak=%.0fHz level=%.1fdB bearing=%.0f° sharp=%.1f siren=%d rising=%d -> %s\\n\",\n                peakHz, levelDb, bearingDeg, sharpness, siren, rising,\n                priority ? \"PRIORITY\" : (siren ? \"rejected (reflection or receding)\" : \"normal\"));\n}\n",
 "magnetic_counter.ino": "// TransitSense · Magnetic vehicle counter and classifier\n// Hardware: ESP32 DevKitC · QMC5883L 3-axis magnetometer (GY-271 module) in a sealed road stud\n// Board: \"ESP32 Dev Module\" (Arduino-ESP32 core 3.x) · Library: PubSubClient (MQTT)\n//\n// A vehicle's steel body bends the Earth's magnetic field above the sensor.\n// The sketch tracks the quiet-road baseline, detects when the field moves away\n// from it, and measures the disturbance's peak and duration. Bigger, longer\n// disturbances mean bigger vehicles. Each detection is published over MQTT.\n// The thresholds are starting points: calibrate them at each site.\n\n#include <Wire.h>\n#include <WiFi.h>\n#include <PubSubClient.h>\n\nconst char *WIFI_SSID = \"your-wifi\";\nconst char *WIFI_PASS = \"your-password\";\nconst char *MQTT_HOST = \"192.168.1.10\";\nconst char *MQTT_TOPIC = \"transitsense/corridor/ts-01/vehicles\";\n\nconst int SDA_PIN = 21, SCL_PIN = 22;\nconst uint8_t QMC_ADDR = 0x0D;\nconst float COUNTS_PER_MILLIGAUSS = 12.0;   // ±2 gauss range: 12000 counts per gauss\n\nconst float START_MG = 15;                  // disturbance that starts a detection\nconst float END_MG = 8;                     // disturbance that ends it (hysteresis)\nconst uint32_t END_HOLD_MS = 150;           // must stay quiet this long to end\nconst float BASELINE_RATE = 0.002;          // slow drift tracking while the road is empty\n\nWiFiClient net;\nPubSubClient mqtt(net);\n\nfloat baseX, baseY, baseZ;\nbool inVehicle = false;\nuint32_t eventStart = 0, quietSince = 0, total = 0;\nfloat eventPeak = 0;\n\nvoid writeRegister(uint8_t reg, uint8_t value) {\n  Wire.beginTransmission(QMC_ADDR);\n  Wire.write(reg);\n  Wire.write(value);\n  Wire.endTransmission();\n}\n\n// Data registers 0x00–0x05 hold X, Y, Z as little-endian signed 16-bit values.\n// Status register 0x06 bit 0 (DRDY) is set when a new sample is ready.\nbool readField(float &x, float &y, float &z) {\n  Wire.beginTransmission(QMC_ADDR);\n  Wire.write(0x06);\n  if (Wire.endTransmission(false) != 0 || Wire.requestFrom(QMC_ADDR, (uint8_t)1) != 1) return false;\n  if (!(Wire.read() & 0x01)) return false;\n  Wire.beginTransmission(QMC_ADDR);\n  Wire.write(0x00);\n  if (Wire.endTransmission(false) != 0 || Wire.requestFrom(QMC_ADDR, (uint8_t)6) != 6) return false;\n  int16_t raw[3];\n  for (int i = 0; i < 3; i++) {\n    uint8_t low = Wire.read();\n    uint8_t high = Wire.read();\n    raw[i] = (int16_t)(low | (high << 8));\n  }\n  x = raw[0] / COUNTS_PER_MILLIGAUSS;\n  y = raw[1] / COUNTS_PER_MILLIGAUSS;\n  z = raw[2] / COUNTS_PER_MILLIGAUSS;\n  return true;\n}\n\nconst char *classify(float peakMg, float seconds) {\n  if (peakMg < 40 && seconds < 0.35) return \"two-wheeler\";\n  if (peakMg > 150 || seconds > 1.0) return \"truck\";\n  return \"car\";\n}\n\nvoid publish(const char *type, float peakMg, float seconds) {\n  char payload[160];\n  snprintf(payload, sizeof(payload),\n           \"{\\\"sensor\\\":\\\"ts-01\\\",\\\"type\\\":\\\"%s\\\",\\\"peak_mg\\\":%.1f,\\\"duration_s\\\":%.2f,\\\"count\\\":%lu}\",\n           type, peakMg, seconds, (unsigned long)total);\n  Serial.println(payload);\n  if (mqtt.connected()) mqtt.publish(MQTT_TOPIC, payload);\n}\n\nvoid keepConnected() {\n  if (WiFi.status() != WL_CONNECTED || mqtt.connected()) return;\n  static uint32_t lastTry = 0;\n  if (millis() - lastTry < 5000) return;\n  lastTry = millis();\n  mqtt.connect(\"transitsense-ts-01\");\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  Wire.begin(SDA_PIN, SCL_PIN);\n  writeRegister(0x0B, 0x01);  // set/reset period, as recommended by the datasheet\n  writeRegister(0x09, 0x09);  // continuous mode, 100 Hz, ±2 gauss, 512× oversampling\n\n  float x, y, z, sx = 0, sy = 0, sz = 0;\n  int samples = 0;\n  uint32_t start = millis();\n  while (samples < 200 && millis() - start < 5000) {  // 2 s calibration on an empty road\n    if (readField(x, y, z)) { sx += x; sy += y; sz += z; samples++; }\n  }\n  if (samples == 0) {\n    Serial.println(\"QMC5883L not responding; check wiring\");\n    while (true) delay(1000);\n  }\n  baseX = sx / samples; baseY = sy / samples; baseZ = sz / samples;\n\n  WiFi.begin(WIFI_SSID, WIFI_PASS);\n  mqtt.setServer(MQTT_HOST, 1883);\n}\n\nvoid loop() {\n  keepConnected();\n  mqtt.loop();\n\n  float x, y, z;\n  if (!readField(x, y, z)) return;\n  float dx = x - baseX, dy = y - baseY, dz = z - baseZ;\n  float deviation = sqrtf(dx * dx + dy * dy + dz * dz);\n  uint32_t now = millis();\n\n  if (!inVehicle) {\n    baseX += BASELINE_RATE * dx;\n    baseY += BASELINE_RATE * dy;\n    baseZ += BASELINE_RATE * dz;\n    if (deviation > START_MG) {\n      inVehicle = true;\n      eventStart = now;\n      eventPeak = deviation;\n      quietSince = 0;\n    }\n  } else {\n    eventPeak = max(eventPeak, deviation);\n    if (deviation < END_MG) {\n      if (!quietSince) quietSince = now;\n      if (now - quietSince >= END_HOLD_MS) {\n        inVehicle = false;\n        float seconds = (quietSince - eventStart) / 1000.0;\n        total++;\n        publish(classify(eventPeak, seconds), eventPeak, seconds);\n      }\n    } else {\n      quietSince = 0;\n    }\n  }\n}\n",
 "parking_camera.ino": "// TransitSense · Parking zone camera (one per zone)\n// Hardware: AI-Thinker ESP32-CAM (OV2640) · 5 V 2 A supply\n// Board: \"AI Thinker ESP32-CAM\" (Arduino-ESP32 core 3.x) · no extra libraries\n//\n// Every 10 s the camera takes a JPEG of its zone and POSTs it to the\n// TransitSense server. The server marks each bay free or occupied (a small\n// image classifier per bay outline), logs arrivals and departures, and runs the\n// bay predictor (see ../parking_server/bay_predictor.py). The reply carries the\n// zone's free-bay count, which this sketch shows on the flash LED:\n// one blink per free bay, or a long glow when the zone is full.\n\n#include <WiFi.h>\n#include <HTTPClient.h>\n#include \"esp_camera.h\"\n\nconst char *WIFI_SSID = \"your-wifi\";\nconst char *WIFI_PASS = \"your-password\";\nconst char *SERVER_URL = \"http://192.168.1.10:8000/api/zones/B/frame\";  // one URL per zone (A, B, C)\nconst uint32_t INTERVAL_MS = 10000;\nconst int FLASH_LED = 4;\n\n// AI-Thinker ESP32-CAM pin map\n#define PWDN_GPIO_NUM 32\n#define RESET_GPIO_NUM -1\n#define XCLK_GPIO_NUM 0\n#define SIOD_GPIO_NUM 26\n#define SIOC_GPIO_NUM 27\n#define Y9_GPIO_NUM 35\n#define Y8_GPIO_NUM 34\n#define Y7_GPIO_NUM 39\n#define Y6_GPIO_NUM 36\n#define Y5_GPIO_NUM 21\n#define Y4_GPIO_NUM 19\n#define Y3_GPIO_NUM 18\n#define Y2_GPIO_NUM 5\n#define VSYNC_GPIO_NUM 25\n#define HREF_GPIO_NUM 23\n#define PCLK_GPIO_NUM 22\n\nuint32_t lastShot = 0;\n\nbool startCamera() {\n  camera_config_t config = {};\n  config.ledc_channel = LEDC_CHANNEL_0;\n  config.ledc_timer = LEDC_TIMER_0;\n  config.pin_d0 = Y2_GPIO_NUM;\n  config.pin_d1 = Y3_GPIO_NUM;\n  config.pin_d2 = Y4_GPIO_NUM;\n  config.pin_d3 = Y5_GPIO_NUM;\n  config.pin_d4 = Y6_GPIO_NUM;\n  config.pin_d5 = Y7_GPIO_NUM;\n  config.pin_d6 = Y8_GPIO_NUM;\n  config.pin_d7 = Y9_GPIO_NUM;\n  config.pin_xclk = XCLK_GPIO_NUM;\n  config.pin_pclk = PCLK_GPIO_NUM;\n  config.pin_vsync = VSYNC_GPIO_NUM;\n  config.pin_href = HREF_GPIO_NUM;\n  config.pin_sccb_sda = SIOD_GPIO_NUM;\n  config.pin_sccb_scl = SIOC_GPIO_NUM;\n  config.pin_pwdn = PWDN_GPIO_NUM;\n  config.pin_reset = RESET_GPIO_NUM;\n  config.xclk_freq_hz = 20000000;\n  config.pixel_format = PIXFORMAT_JPEG;\n  config.frame_size = FRAMESIZE_SVGA;  // 800×600 is enough to read 10 bay outlines\n  config.jpeg_quality = 12;\n  config.fb_count = 1;\n  config.fb_location = CAMERA_FB_IN_PSRAM;\n  config.grab_mode = CAMERA_GRAB_LATEST;\n  return esp_camera_init(&config) == ESP_OK;\n}\n\nvoid blinkFreeBays(int freeBays) {\n  if (freeBays <= 0) {\n    digitalWrite(FLASH_LED, HIGH);\n    delay(600);\n    digitalWrite(FLASH_LED, LOW);\n    return;\n  }\n  for (int i = 0; i < freeBays && i < 10; i++) {\n    digitalWrite(FLASH_LED, HIGH);\n    delay(40);\n    digitalWrite(FLASH_LED, LOW);\n    delay(160);\n  }\n}\n\nvoid sendFrame() {\n  camera_fb_t *frame = esp_camera_fb_get();\n  if (!frame) {\n    Serial.println(\"Capture failed\");\n    return;\n  }\n  HTTPClient http;\n  http.begin(SERVER_URL);\n  http.addHeader(\"Content-Type\", \"image/jpeg\");\n  int status = http.POST(frame->buf, frame->len);\n  esp_camera_fb_return(frame);\n\n  if (status == 200) {\n    String reply = http.getString();  // e.g. {\"zone\":\"B\",\"free\":3,\"occupied\":7}\n    int at = reply.indexOf(\"\\\"free\\\":\");\n    int freeBays = at >= 0 ? reply.substring(at + 7).toInt() : -1;\n    Serial.printf(\"Zone update sent, %d bays free\\n\", freeBays);\n    if (freeBays >= 0) blinkFreeBays(freeBays);\n  } else {\n    Serial.printf(\"Upload failed: HTTP %d\\n\", status);\n  }\n  http.end();\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(FLASH_LED, OUTPUT);\n  if (!startCamera()) {\n    Serial.println(\"Camera init failed; check the ribbon cable\");\n    while (true) delay(1000);\n  }\n  WiFi.begin(WIFI_SSID, WIFI_PASS);\n  while (WiFi.status() != WL_CONNECTED) delay(250);\n  Serial.println(\"Wi-Fi connected: \" + WiFi.localIP().toString());\n}\n\nvoid loop() {\n  if (WiFi.status() != WL_CONNECTED) {\n    WiFi.reconnect();\n    delay(1000);\n    return;\n  }\n  if (millis() - lastShot >= INTERVAL_MS) {\n    lastShot = millis();\n    sendFrame();\n  }\n}\n",
 "bay_predictor.py": "\"\"\"TransitSense · Bay predictor (runs on the server that receives the ESP32-CAM frames).\n\nThe zone cameras report which bays are occupied. From the garage's history the\nserver knows roughly how many cars arrive and leave per minute, and which parked\ncars are likely to leave first (longest-parked, expiring tickets, ...). To answer\n\"Will there be a bay for me when I arrive, and where?\" it replays the predicted\ndepartures and arrivals up to the driver's arrival time, bay by bay:\n\n* a departure frees that car's bay;\n* every earlier arrival takes the best free bay (shortest drive from the entrance);\n* the driver is offered the best bay still free on arrival, plus a backup.\n\nIf no bay is left, it searches later arrival times for the next predicted opening.\nThis is the same logic the website demo runs (dist/model.mjs, planArrival).\n\"\"\"\n\nimport math\nfrom dataclasses import dataclass, field\n\n\n@dataclass\nclass Plan:\n    bay: int | None\n    backup: int | None\n    free_bays: list[int]\n    freed_at: float | None          # minutes until the offered bay is freed (None = free already)\n    turned_away: int\n    events: list[tuple[float, str, int | None]] = field(default_factory=list)\n\n\ndef round_half_up(x):\n    return math.floor(x + 0.5)  # matches JavaScript's Math.round (Python's round() rounds halves to even)\n\n\ndef plan_arrival(occupied, minutes, cost, depart_order, arrive_per_min=0.9, depart_per_min=0.45):\n    state = list(occupied)\n    departures = min(round_half_up(minutes * depart_per_min), len(depart_order))\n    arrivals = round_half_up(minutes * arrive_per_min)\n    events = [((k + 0.5) / depart_per_min, \"depart\", depart_order[k]) for k in range(departures)]\n    events += [((k + 0.5) / arrive_per_min, \"arrive\", None) for k in range(arrivals)]\n    events.sort(key=lambda e: (e[0], e[1] != \"depart\"))\n\n    def best_free():\n        free = [i for i, taken in enumerate(state) if not taken]\n        return min(free, key=lambda i: (cost[i], i)) if free else None\n\n    freed_at, played, turned_away = {}, [], 0\n    for t, kind, bay in events:\n        if kind == \"depart\":\n            state[bay] = False\n            freed_at[bay] = t\n        else:\n            bay = best_free()\n            if bay is None:\n                turned_away += 1\n            else:\n                state[bay] = True\n                freed_at.pop(bay, None)\n        played.append((t, kind, bay))\n\n    free_bays = sorted((i for i, taken in enumerate(state) if not taken), key=lambda i: (cost[i], i))\n    bay = free_bays[0] if free_bays else None\n    return Plan(\n        bay=bay,\n        backup=free_bays[1] if len(free_bays) > 1 else None,\n        free_bays=free_bays,\n        freed_at=freed_at.get(bay) if bay is not None else None,\n        turned_away=turned_away,\n        events=played,\n    )\n\n\ndef next_opening(occupied, minutes, cost, depart_order, horizon=30, **rates):\n    for m in range(minutes + 1, minutes + horizon + 1):\n        if plan_arrival(occupied, m, cost, depart_order, **rates).bay is not None:\n            return m\n    return None\n\n\ndef bay_name(index, bays_per_zone=10):\n    return f\"{'ABC'[index // bays_per_zone]}-{index % bays_per_zone + 1:02d}\"\n\n\nif __name__ == \"__main__\":\n    # 30 bays in zones A, B, C; True = occupied (as reported by the three ESP32-CAMs).\n    occupied = [i in {0, 1, 3, 4, 6, 7, 10, 11, 13, 14, 16, 18, 20, 21, 22, 24, 26, 28} for i in range(30)]\n    cost = [abs(i % 10 - 9) * 3.6 + (10 if i < 10 else 5 if i < 20 else 0) for i in range(30)]  # metres from entrance\n    depart_order = [i for i, taken in enumerate(occupied) if taken]  # from camera history: who leaves first\n\n    for eta, rates in [(10, {}), (12, {\"arrive_per_min\": 1.5, \"depart_per_min\": 0.3})]:\n        plan = plan_arrival(occupied, eta, cost, depart_order, **rates)\n        if plan.bay is None:\n            later = next_opening(occupied, eta, cost, depart_order, **rates)\n            print(f\"Arriving in {eta} min: garage predicted full; next opening in {later} min\")\n        else:\n            reason = \"free now\" if plan.freed_at is None else f\"freed by a departure at ~{plan.freed_at:.0f} min\"\n            print(f\"Arriving in {eta} min: go to bay {bay_name(plan.bay)} ({reason}); backup {bay_name(plan.backup) if plan.backup is not None else 'none'}\")\n"
};
